/* Select the present MD/AD on entry, without changing period calculations. */
(()=>{'use strict';function current(){try{const data=KPTransit.currentPeriods(),offset=data.offset??Number(KPHomeDasha.getData().timeZoneHours),local=new Date(Date.now()+offset*3600000).toISOString();document.getElementById('dp-date').value=local.slice(0,10);document.getElementById('dp-time').value=local.slice(11,19);document.getElementById('dp-offset').value=offset;KPDashaPromise.refresh(true,true);}catch(e){const status=document.getElementById('dp-status');if(status)status.textContent=e.message;}}
function init(){const section=document.getElementById('dasha-promise');let active=section.classList.contains('active');new MutationObserver(()=>{const next=section.classList.contains('active');if(next&&!active)current();active=next;}).observe(section,{attributes:true,attributeFilter:['class']});if(active)current();}
window.KPDashaCurrentSelection=Object.freeze({current});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,0));else init();})();
